<?php
declare(strict_types=1);
namespace Tests\Integration;
use PDO;
use PHPUnit\Framework\TestCase;
require_once dirname(__DIR__,2).'/includes/shop_inventory.php';
final class ShopInventoryTest extends TestCase {
 private PDO $p;
 protected function setUp():void {
  $p=$this->p=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$p->exec("PRAGMA foreign_keys=ON;CREATE TABLE treneri(id INT PRIMARY KEY,aktivni INT);CREATE TABLE staff_user_positions(trainer_id INT,position_code TEXT);CREATE TABLE staff_superadmins(trainer_id INT);INSERT INTO treneri VALUES(1,1),(2,1),(3,1),(4,0);INSERT INTO staff_user_positions VALUES(1,'catalog_manager'),(1,'finance_manager'),(1,'order_operator'),(2,'catalog_manager'),(2,'finance_manager'),(3,'order_operator'),(4,'catalog_manager');CREATE TABLE shop_products(id INT PRIMARY KEY,offer_type TEXT,name TEXT);INSERT INTO shop_products VALUES(1,'goods','LOCALHOST shirt'),(2,'program','LOCALHOST course');CREATE TABLE shop_variants(id INT PRIMARY KEY,product_id INT,sku TEXT,unit_code TEXT,stock_quantity_decimal TEXT);INSERT INTO shop_variants VALUES(1,1,'LOCALHOST-M','piece','7'),(2,1,'LOCALHOST-L','piece',NULL),(3,2,'LOCALHOST-PROGRAM','person',NULL);CREATE TABLE shop_orders(id INT PRIMARY KEY,status TEXT,payment_status TEXT);CREATE TABLE shop_order_items(id INT PRIMARY KEY,order_id INT,variant_id INT,quantity INT);");$m=require dirname(__DIR__,2).'/migrations/20261022230000_shop_inventory.php';$m['up']($p);self::assertTrue($m['verify']($p));\shopInventoryConfigure($p,1,'LOCALHOST warehouse','fifo','LOCALHOST accountant approval','LOCALHOST approved FIFO method.',true);
 }
 private function opening(int $quantity=10,?int $cost=100):array {return \shopInventoryOpen($this->p,1,1,['physical_quantity'=>$quantity,'blocked_quantity'=>0,'unit_cost_minor'=>$cost,'evidence'=>'LOCALHOST signed count and valuation','effective_on'=>'2026-10-01'],'LOCALHOST verified opening stock.',true,'opening-one');}
 private function reserve(int $qty=3,int $item=1):void {$this->p->exec("INSERT INTO shop_orders VALUES($item,'placed','paid');INSERT INTO shop_order_items VALUES($item,$item,1,$qty)");\shopInventoryTransaction($this->p,fn()=>\shopInventoryReserveInTransaction($this->p,1,$item,$item,$qty,'reserve-'.$item));}
 private function issue(int $qty=2,int $item=1,string $key='issue-one'):array{return \shopInventoryTransaction($this->p,fn()=>\shopInventoryIssueInTransaction($this->p,$item,$qty,$key,1,'LOCALHOST actual handoff.',['effective_on'=>date('Y-m-d')]));}
 private function quantities(int $p,int $r,int $b,int $a):void {$x=\shopInventoryBalance($this->p,1);self::assertSame([$p,$r,$b,$a],[$x['physical_quantity'],$x['reserved_quantity'],$x['blocked_quantity'],$x['available_quantity']]);self::assertSame((string)$a,(string)$this->p->query('SELECT stock_quantity_decimal FROM shop_variants WHERE id=1')->fetchColumn());}
 public function testReserveIssueReturnBlockedAndReleaseKeepPhysicalTruth():void {$this->opening();$this->reserve();$this->quantities(10,3,0,7);$issue=$this->issue();$this->quantities(8,1,0,7);$returned=\shopInventoryTransaction($this->p,fn()=>\shopInventoryReturnInTransaction($this->p,(int)$issue['id'],1,'return-one',1,'LOCALHOST physical returned garment.'));$this->quantities(9,1,1,7);\shopInventoryDisposition($this->p,1,1,1,'unblock','LOCALHOST inspected and saleable.',true,'unblock-one',['return_movement_id'=>$returned['id']]);$this->quantities(9,1,0,8);\shopInventoryTransaction($this->p,fn()=>\shopInventoryReleaseInTransaction($this->p,1,'release-one'));$this->quantities(9,0,0,9);}
 public function testRetriesAreIdempotentButChangedPayloadCannotReuseKey():void {$this->opening();$this->reserve();$a=$this->issue();$b=$this->issue();self::assertSame($a['id'],$b['id']);$this->quantities(8,1,0,7);$this->expectException(\ShopInventoryException::class);$this->issue(1);}
 public function testUnknownReceiptPriceIsNullUntilAuditedCorrectionAndOldMovementImmutable():void {$this->opening(3,null);$this->reserve(1);$i=$this->issue(1);self::assertNull($i['cost_minor']);$lot=(int)$this->p->query('SELECT id FROM shop_stock_lots')->fetchColumn();\shopInventoryCorrectCost($this->p,1,$lot,250,'2026-10-03','LOCALHOST late supplier invoice','LOCALHOST complete missing valuation.',true,'cost-one');self::assertNull($this->p->query("SELECT cost_minor FROM shop_stock_movements WHERE kind='issue'")->fetchColumn());self::assertSame(1,(int)$this->p->query('SELECT issued_quantity FROM shop_stock_cost_revisions')->fetchColumn());self::assertSame(2,(int)$this->p->query('SELECT remaining_quantity FROM shop_stock_cost_revisions')->fetchColumn());}
 public function testReceiptIncludesSupplierPartialDeliveryAndBlockedUnits():void {$this->opening(0,null);$input=['quantity'=>8,'expected_quantity'=>10,'blocked_quantity'=>1,'unit_cost_minor'=>120,'supplier'=>'LOCALHOST supplier','supplier_reference'=>'LOCALHOST invoice #1','cost_evidence'=>'LOCALHOST invoice + freight split','effective_on'=>'2026-10-02'];$a=\shopInventoryReceive($this->p,1,1,$input,'LOCALHOST partial physical delivery.',true,'receipt-1');$b=\shopInventoryReceive($this->p,1,1,$input,'LOCALHOST partial physical delivery.',true,'receipt-1');self::assertSame($a['id'],$b['id']);$this->quantities(8,0,1,7);self::assertSame(960,(int)$a['cost_minor']);}
 public function testBlockedSupplierReturnIsLinkedAndNotMoney():void {$opening=$this->opening(3);\shopInventoryDisposition($this->p,1,1,1,'block','LOCALHOST damaged supplier piece.',true,'block-1');$m=\shopInventoryDisposition($this->p,1,1,1,'supplier_return','LOCALHOST actually returned supplier.',true,'supplier-return',['source_movement_id'=>$opening['id'],'blocked'=>true]);self::assertSame(100,(int)$m['cost_minor']);$this->quantities(2,0,0,2);}
 public function testOpeningRequiresExactVerifiedCurrentOrdersAndRejectsCompleted():void {$this->p->exec("INSERT INTO shop_orders VALUES(1,'placed','paid'),(2,'completed','paid');INSERT INTO shop_order_items VALUES(1,1,1,2),(2,2,1,5)");$m=\shopInventoryOpen($this->p,1,1,['physical_quantity'=>5,'blocked_quantity'=>1,'unit_cost_minor'=>100,'reservations'=>[1=>2],'evidence'=>'LOCALHOST individually verified two unissued pieces','effective_on'=>'2026-10-01'],'LOCALHOST verified open order mapping.',true,'open-mapped');$this->quantities(5,2,1,2);self::assertSame(1,(int)$this->p->query('SELECT COUNT(*) FROM shop_stock_reservations')->fetchColumn());}
 public function testUnmappedOpenOrderRejectsOpeningWithoutPartialChanges():void {$this->p->exec("INSERT INTO shop_orders VALUES(1,'ready','paid');INSERT INTO shop_order_items VALUES(1,1,1,2)");try{$this->opening();self::fail('Expected rejection');}catch(\ShopInventoryException){self::assertNull(\shopInventoryBalance($this->p,1));}}
 public function testCountPreservesReservationsAndRequiresAnotherApprover():void {$this->opening();$this->reserve();$c=\shopInventoryCountStart($this->p,1,1,'LOCALHOST signed ten-piece count','LOCALHOST count all including reserved.',true);$done=\shopInventoryCountApprove($this->p,2,(int)$c['id'],9,1,'LOCALHOST discrepancy independently checked.',true);self::assertSame('approved',$done['status']);$this->quantities(9,3,1,5);}
 public function testStaleCountCannotOverwriteLaterReceipt():void {$this->opening();$c=\shopInventoryCountStart($this->p,1,1,'LOCALHOST count snapshot','LOCALHOST physical stock count.',true);$this->reserve(1);$this->expectExceptionMessage('Během počítání');\shopInventoryCountApprove($this->p,2,(int)$c['id'],10,0,'LOCALHOST stale count submission.',true);}
 public function testCountShortageDoesNotSilentlyReleaseReservations():void {$this->opening();$this->reserve(3);$c=\shopInventoryCountStart($this->p,1,1,'LOCALHOST count snapshot','LOCALHOST physical stock count.',true);try{\shopInventoryCountApprove($this->p,2,(int)$c['id'],2,0,'LOCALHOST cannot cover orders.',true);self::fail();}catch(\ShopInventoryException){$this->quantities(10,3,0,7);}}
 public function testReturnCannotExceedIssuedQuantityOrTouchAnotherBatch():void {$this->opening();$this->reserve();$i=$this->issue(2);$r=\shopInventoryTransaction($this->p,fn()=>\shopInventoryReturnInTransaction($this->p,(int)$i['id'],1,'return-one',1,'LOCALHOST first physical return.'));try{\shopInventoryTransaction($this->p,fn()=>\shopInventoryReturnInTransaction($this->p,(int)$i['id'],2,'return-two',1,'LOCALHOST duplicate extra pieces.'));self::fail();}catch(\ShopInventoryException){$this->quantities(9,1,1,7);} $this->expectException(\ShopInventoryException::class);\shopInventoryDisposition($this->p,1,1,2,'writeoff','LOCALHOST cannot use another batch.',true,'bad-writeoff',['return_movement_id'=>$r['id']]);}
 public function testExchangeDoesNotRewriteOriginalOrderOrCreateMoney():void {$this->opening();$this->reserve(1);$this->issue(1);$r=\shopInventoryTransaction($this->p,fn()=>\shopInventoryReserveExchangeInTransaction($this->p,100,1,1,'exchange-r',1,'LOCALHOST replacement garment.'));\shopInventoryTransaction($this->p,fn()=>\shopInventoryIssueExchangeInTransaction($this->p,(int)$r['id'],1,'exchange-i',1,'LOCALHOST actual replacement issue.'));self::assertSame(1,(int)$this->p->query('SELECT COUNT(*) FROM shop_orders')->fetchColumn());self::assertSame(1,(int)$this->p->query('SELECT variant_id FROM shop_order_items')->fetchColumn());$this->quantities(8,0,0,8);}
 public function testServiceNeverBecomesPhysicalStock():void {$this->expectException(\ShopInventoryException::class);\shopInventoryOpen($this->p,1,3,['physical_quantity'=>1,'evidence'=>'LOCALHOST impossible service stock','effective_on'=>'2026-10-01'],'LOCALHOST cannot count course.',true,'service');}
 public function testQuantityRejectsFractionsAndInactiveOrRevokedActorCannotWrite():void {try{\shopInventoryQuantity('0.5');self::fail();}catch(\ShopInventoryException){}$this->opening();$this->p->exec('DELETE FROM staff_user_positions WHERE trainer_id=1');$this->expectException(\ShopInventoryException::class);\shopInventoryDisposition($this->p,1,1,1,'internal_issue','LOCALHOST revoked grant action.',true,'revoked');}
 public function testFifoMixedCostReturnPreservesEveryOriginalPortion():void {$this->opening(1,100);\shopInventoryReceive($this->p,1,1,['quantity'=>1,'unit_cost_minor'=>200,'supplier'=>'LOCALHOST supplier','supplier_reference'=>'LOCALHOST-2','cost_evidence'=>'LOCALHOST invoice','effective_on'=>'2026-10-02'],'LOCALHOST second FIFO batch.',true,'receipt2');$this->reserve(2);$i=$this->issue(2);self::assertSame(300,(int)$i['cost_minor']);$r=\shopInventoryTransaction($this->p,fn()=>\shopInventoryReturnInTransaction($this->p,(int)$i['id'],2,'return-mixed',1,'LOCALHOST physical return both prices.'));self::assertSame(300,(int)$r['cost_minor']);$s=$this->p->prepare('SELECT unit_cost_minor FROM shop_stock_lots WHERE source_movement_id=? ORDER BY id');$s->execute([$r['id']]);self::assertSame([100,200],array_map('intval',$s->fetchAll(PDO::FETCH_COLUMN)));}
 public function testCostRevisionCannotReorderAlreadyRecordedValuation():void {$this->opening();$lot=(int)$this->p->query('SELECT id FROM shop_stock_lots')->fetchColumn();\shopInventoryCorrectCost($this->p,1,$lot,200,'2026-10-10','LOCALHOST corrected invoice','LOCALHOST later approved valuation.',true,'cost-later');$this->expectException(\ShopInventoryException::class);\shopInventoryCorrectCost($this->p,1,$lot,150,'2026-10-09','LOCALHOST older invoice','LOCALHOST cannot reorder chronology.',true,'cost-older');}
 public function testCountAdjustmentKeepsFifoPhysicalAndBlockedLotTotals():void {$this->opening(10);$this->reserve(2);\shopInventoryDisposition($this->p,1,1,3,'block','LOCALHOST initial blocked stock.',true,'block-count');foreach([[6,4],[12,5],[10,0]]as[$physical,$blocked]){$c=\shopInventoryCountStart($this->p,1,1,'LOCALHOST independently signed count','LOCALHOST recount physical and blocked.',true);\shopInventoryCountApprove($this->p,2,(int)$c['id'],$physical,$blocked,'LOCALHOST verified difference approval.',true);$lots=$this->p->query('SELECT SUM(remaining_quantity) p,SUM(blocked_quantity) b FROM shop_stock_lots WHERE variant_id=1')->fetch(PDO::FETCH_ASSOC);self::assertSame([$physical,$blocked],[(int)$lots['p'],(int)$lots['b']]);$this->quantities($physical,2,$blocked,$physical-2-$blocked);}}

}
